import * as path from 'path';
import { repoPaths } from '../lib/paths';
import { writeFileAtomic, writeJson, sha256 } from '../lib/fsutil';
import { TOOL_VERSION } from '../lib/config';

/**
 * The Node script every git and Claude Code hook calls (MASTER 12). It is plain JavaScript with no
 * dependencies, generated by deterministic local logic (I-7), and it can never make a hook fail:
 * the process always exits 0 (I-2, I-3), and it does nothing at all when the kill switch is on (D-31).
 */
export const RUNNER_NAME = 'ds-hook.js';
export const RUNNER_MARKER = 'devsarathi/hooks/ds-hook.js';

export function runnerSource(): string {
  return `#!/usr/bin/env node
'use strict';
// Generated by DevSarathi ${TOOL_VERSION}. Fail-open: this script always exits 0.
// It only starts DevSarathi's own CLI (path recorded in runtime.json); it runs nothing else.
var fs = require('fs');
var path = require('path');
var cp = require('child_process');

function done() { process.exit(0); }

try {
  var root = path.resolve(__dirname, '..', '..', '..');
  var name = process.argv[2];
  var rest = process.argv.slice(3);

  var disabled = false;
  try {
    disabled = JSON.parse(fs.readFileSync(path.join(root, '.claude', 'devsarathi', 'config.json'), 'utf8')).disabled === true;
  } catch (e) { /* unreadable config: carry on, the CLI reports it */ }
  if (disabled) done();

  var runtime = {};
  try { runtime = JSON.parse(fs.readFileSync(path.join(__dirname, 'runtime.json'), 'utf8')); } catch (e) { /* missing */ }

  function notice(msg) {
    try {
      fs.appendFileSync(path.join(root, '.claude', 'devsarathi', 'notices.jsonl'),
        JSON.stringify({ at: new Date().toISOString(), source: String(name), message: msg }) + '\\n');
    } catch (e) { /* ignore */ }
    try { process.stderr.write('[devsarathi] ' + msg + '\\n'); } catch (e) { /* ignore */ }
  }

  if (!runtime.cli || !fs.existsSync(runtime.cli)) {
    notice(name + ' did not run: DevSarathi is not installed at the recorded location. Reinstall it, then run: devsarathi init');
    done();
  }

  var args = [runtime.cli, 'hook', String(name), '-C', root].concat(rest);
  var res = cp.spawnSync(runtime.node || process.execPath, args, { stdio: 'inherit', windowsHide: true });
  if (res.error) notice(name + ' did not run: ' + res.error.message);
} catch (err) {
  try { process.stderr.write('[devsarathi] hook did not run: ' + (err && err.message) + '\\n'); } catch (e) { /* ignore */ }
}
done();
`;
}

export function installRunner(root: string): { path: string; hash: string } {
  const p = repoPaths(root);
  const file = path.join(p.hooks, RUNNER_NAME);
  const src = runnerSource();
  writeFileAtomic(file, src);
  // Where the CLI lives right now. Refreshed by init and migrate; the runner fails open if it moves.
  const cli = path.resolve(__dirname, '..', '..', '..', '..', 'bin', 'devsarathi.js');
  writeJson(path.join(p.hooks, 'runtime.json'), { node: process.execPath, cli, version: TOOL_VERSION, writtenAt: new Date().toISOString() });
  return { path: file, hash: sha256(src) };
}
